/// <summary>
/// Class entry point. The system will call this method when a designated menu 
/// is selected or when execution starts and this class is set as the startup class.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    Map headerMap = new Map(Types::String, Types::String);
    headerMap.insert('5637180578','PackingSlip');
    headerMap.insert('5637180581','PackingSlip');

    MapIterator         mapIterator = new MapIterator(headerMap);
    container           conRecord;

    while (mapIterator.more())
    {
        conRecord += mapIterator.key();
        mapIterator.next();
    }

    MenuFunction    menuFunction;
    //CustPackingSlipJour packingSlipJour = CustPackingSlipJour::find("SO00125111");

    Args            args = new Args();
    args.parm(con2Str(conRecord));
    //args.record(_SalesTable);

    menuFunction = new MenuFunction(menuitemActionStr(METSOShipment), MenuItemType::Action);
    menuFunction.run(args);
}
